using Aion.Protocol.Native;

/// <summary>
/// Byte-exact checks of <see cref="PlayerPackets"/> (and the existing GamePackets builders the
/// official server also uses for other players) against official server messages from
/// research/local/capture-13700-20261013-144836-cad11c76/combat-audit/messages.jsonl
/// (hex = opcode LE + body; "#n" is the message index there). Generated from the decode
/// scripts; the values are the decoded fields of each sample.
/// </summary>
public static class PlayerPacketChecks
{
    static int passed;

    static double F(uint bits) => BitConverter.UInt32BitsToSingle(bits);
    static Vector3d V(uint x, uint y, uint z) => new(F(x), F(y), F(z));
    static double D(int raw) => raw * 360.0 / 65536;

    static void Same(string name, byte[] built, string officialHex)
    {
        var expected = Convert.FromHexString(officialHex);
        if (!built.AsSpan().SequenceEqual(expected))
        {
            var at = 0;
            while (at < Math.Min(built.Length, expected.Length) && built[at] == expected[at]) at++;
            throw new InvalidOperationException($"PlayerPackets mismatch: {name} at byte {at} (built {built.Length}, official {expected.Length} bytes)\n built {Convert.ToHexString(built)}\n  want {officialHex.ToUpperInvariant()}");
        }
        passed++;
    }

    static void Check(bool condition, string name)
    {
        if (!condition) throw new InvalidOperationException("PlayerPackets check failed: " + name);
        passed++;
    }

