        Check(equips[3].Godstones!.Count == 3 && equips[1].Godstones!.Count == 0, "items carry three godstone slots, empty slots none");
        var plain = PlayerPackets.CharAppear(new OtherCharacter { Key = 7, Name = "A", Direction = 90, Reason = 0 });
        Check(plain[0] == 0x45 && plain[1] == 0x36 && plain[2] == 7 && BitConverter.ToUInt32(plain, 3) == 1, "appear mask is bit 0 only for a standing EnterMap appear");
        var moving = PlayerPackets.CharAppear(new OtherCharacter { Key = 7, Name = "A", MoveState = 1, Sprinting = true, DeadReckoning = true, VoiceType = 2 });
        Check(BitConverter.ToUInt32(moving, 3) == (1u | 1 << 2 | 1 << 4 | 1 << 12 | 1 << 13 | 1 << 18), "appear mask bits for run, sprint, dead reckoning, reason, voice");
        Check(PlayerPackets.MoveOffset(5033, 0, 0, 0, 0, 0).Length == 2 + 2 + 1 + 1 + 4, "zero offsets are omitted");
        Check(PlayerPackets.CharDisappear(300).SequenceEqual(new byte[] { 0x47, 0x36, 0xac, 0x02, 1, 0 }), "disappear defaults to reason 1 (out of range), no effect");
